owners.common_read:
@id("bound-tool:call")
permit (
  principal,
  action == slangGraph::Action::"call",
  resource == slangGraph::Tool::"common_read"
);

@id("bound-tool:fs:read")
permit (
  principal,
  action == slangGraph::Action::"fs::read",
  resource
) when {
  context.tool == slangGraph::Tool::"common_read"
};
